document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".badge-item"),t=document.querySelector(".btn-see-more");e.forEach(e=>{e.addEventListener("click",function(){const e=this.querySelector("h3").textContent;showToast(`Viewing details for: ${e}`,"info")})}),t&&t.addEventListener("click",function(){showToast("Loading badge path...","info")});document.querySelectorAll(".progress-fill").forEach(e=>{const t=e.style.width;e.style.width="0",setTimeout(()=>{e.style.transition="width 1s ease-out",e.style.width=t},100)})});